// include benchmark-specific definitions (same role as adi.h in C version)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Initialization: translate init_array() to a Halide pipeline.
// -----------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // C code:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     u[i][j] = (DATA_TYPE)(i + n - j) / n;
    //
    // C array layout: u[i][j]
    // Halide Buffer layout: u(j, i)  (dimension 0 is j, dimension 1 is i).

    Var i("i"), j("j");
    Func init_u("init_u");

    // Note: (i + n - j) is an Expr; n is an int that is implicitly lifted
    // to an Expr. We then cast the result to num_t and divide by num_t(n).
    init_u(j, i) = cast<num_t>(i + n - j) / cast<num_t>(n);

    init_u.realize(u);
}

// -----------------------------------------------------------------------------
// Main computational kernel: ADI solver in plain C++ loops over Halide Buffers.
//
// The ADI algorithm has strong loop-carried dependencies (Thomas algorithm
// along rows/columns). Per the translation rules for dynamic programming
// patterns, we keep these recurrences as host-side loops operating on
// Halide::Buffer objects, rather than forcing them into illegal Halide
// self-referential Func definitions.
// -----------------------------------------------------------------------------
static void kernel_adi(int tsteps, int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Map: original C u[i][j] -> u(j, i) etc.
    // Dimension 0 (x) = j, Dimension 1 (y) = i.

    num_t DX, DY, DT;
    num_t B1, B2;
    num_t mul1, mul2;
    num_t a, b, c, d, e, f;

    DX = (num_t)1.0 / (num_t)n;
    DY = (num_t)1.0 / (num_t)n;
    DT = (num_t)1.0 / (num_t)tsteps;
    B1 = (num_t)2.0;
    B2 = (num_t)1.0;
    mul1 = B1 * DT / (DX * DX);
    mul2 = B2 * DT / (DY * DY);

    a = -mul1 / (num_t)2.0;
    b = (num_t)1.0 + mul1;
    c = a;
    d = -mul2 / (num_t)2.0;
    e = (num_t)1.0 + mul2;
    f = d;

    for (int t = 1; t <= tsteps; t++) {
        // -------------------------------------------------------------
        // Column sweep
        // -------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = (num_t)1.0;

            // p[i][0] = 0.0;
            p(0, i) = (num_t)0.0;

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            for (int j = 1; j < n - 1; j++) {
                // p[i][j] = -c / (a*p[i][j-1] + b);
                {
                    num_t denom = a * p(j - 1, i) + b;
                    p(j, i) = -c / denom;
                }

                // q[i][j] =
                //   (-d*u[j][i-1] + (1 + 2*d)*u[j][i] - f*u[j][i+1] - a*q[i][j-1])
                //   / (a*p[i][j-1] + b);
                {
                    num_t u_j_im1 = u(i - 1, j); // u[j][i-1]
                    num_t u_j_i   = u(i,     j); // u[j][i]
                    num_t u_j_ip1 = u(i + 1, j); // u[j][i+1]
                    num_t q_prev  = q(j - 1, i); // q[i][j-1]
                    num_t p_prev  = p(j - 1, i); // p[i][j-1]

                    num_t numerator =
                        (-d * u_j_im1) +
                        ((num_t)1.0 + (num_t)2.0 * d) * u_j_i -
                        f * u_j_ip1 -
                        a * q_prev;

                    num_t denom = a * p_prev + b;

                    q(j, i) = numerator / denom;
                }
            }

            // v[n-1][i] = 1.0;
            v(i, n - 1) = (num_t)1.0;

            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                num_t p_ij   = p(j,     i);
                num_t v_jp1i = v(i, j + 1);
                num_t q_ij   = q(j,     i);

                v(i, j) = p_ij * v_jp1i + q_ij;
            }
        }

        // -------------------------------------------------------------
        // Row sweep
        // -------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = (num_t)1.0;

            // p[i][0] = 0.0;
            p(0, i) = (num_t)0.0;

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            for (int j = 1; j < n - 1; j++) {
                // p[i][j] = -f / (d*p[i][j-1] + e);
                {
                    num_t denom = d * p(j - 1, i) + e;
                    p(j, i) = -f / denom;
                }

                // q[i][j] =
                //   (-a*v[i-1][j] + (1 + 2*a)*v[i][j] - c*v[i+1][j] - d*q[i][j-1])
                //   / (d*p[i][j-1] + e);
                {
                    num_t v_im1_j = v(j, i - 1); // v[i-1][j]
                    num_t v_i_j   = v(j, i);     // v[i][j]
                    num_t v_ip1_j = v(j, i + 1); // v[i+1][j]
                    num_t q_prev  = q(j - 1, i); // q[i][j-1]
                    num_t p_prev  = p(j - 1, i); // p[i][j-1]

                    num_t numerator =
                        (-a * v_im1_j) +
                        ((num_t)1.0 + (num_t)2.0 * a) * v_i_j -
                        c * v_ip1_j -
                        d * q_prev;

                    num_t denom = d * p_prev + e;

                    q(j, i) = numerator / denom;
                }
            }

            // u[i][n-1] = 1.0;
            u(n - 1, i) = (num_t)1.0;

            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                num_t p_ij   = p(j,     i);
                num_t u_ijp1 = u(j + 1, i);
                num_t q_ij   = q(j,     i);

                u(j, i) = p_ij * u_ijp1 + q_ij;
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size (matches the C version: N, TSTEPS from PolyBench headers)
    int n      = N;
    int tsteps = TSTEPS;

    // Buffers for u, v, p, q.
    // C arrays are u[N][N]; mapping is u(i_c, j_c) -> u_buf(j_c, i_c).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u using a Halide pipeline.
    init_array(n, u);

    // Measure the execution time of the ADI kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the output (similar to print_array in the C version).
    // We print u[i][j] as u(j, i) to std::cerr, one value per line.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing in seconds (like gemm.cpp example).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
