#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (problem sizes, DATA_TYPE, etc.)
#include "defines.hpp"

// include benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using namespace Halide;

using num_t = DATA_TYPE;

/**
 * Initialize u[i][j] = (i + n - j) / n
 *
 * C layout:    u[i][j], with i in [0, n), j in [0, n)
 * Halide layout: Buffer<num_t,2> u(j, i)  (dim 0 = j, dim 1 = i)
 *
 * So C's u[i][j] corresponds to u(j, i) in the Buffer.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> u) {
    Var i("i"), j("j");
    Func init_u("init_u");

    // Note: i and j are 32-bit ints by default in Halide.
    Expr n_expr = n;

    // C: u[i][j] = (DATA_TYPE)(i + n - j) / n;
    // Buffer: u(j, i)
    init_u(j, i) = cast<num_t>(i + n_expr - j) / cast<num_t>(n_expr);

    // Realize directly into the provided Buffer.
    init_u.realize(u);
}

/**
 * Main computational kernel, translated to operate on Halide::Buffer objects.
 *
 * Original C prototype:
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * We keep the algorithm and traversal order identical, but access data
 * via Halide::Buffer<num_t,2>, using the mapping:
 *
 *   C:   a[i][j]
 *   HL:  a(j, i)     (dim 0 = j, dim 1 = i)
 *
 * This respects the translation rule for 2D C arrays.
 */
static
void kernel_adi(int tsteps, int n,
                Halide::Buffer<num_t, 2> u,
                Halide::Buffer<num_t, 2> v,
                Halide::Buffer<num_t, 2> p,
                Halide::Buffer<num_t, 2> q) {
    // Scalar parameters (same formulas as in the original code).
    num_t DX   = num_t(1.0) / num_t(n);
    num_t DY   = num_t(1.0) / num_t(n);
    num_t DT   = num_t(1.0) / num_t(tsteps);
    num_t B1   = num_t(2.0);
    num_t B2   = num_t(1.0);
    num_t mul1 = B1 * DT / (DX * DX);
    num_t mul2 = B2 * DT / (DY * DY);

    num_t a = -mul1 / num_t(2.0);
    num_t b = num_t(1.0) + mul1;
    num_t c = a;
    num_t d = -mul2 / num_t(2.0);
    num_t e = num_t(1.0) + mul2;
    num_t f = d;

    // Time-stepping loop
    for (int t = 0; t < tsteps; t++) {
        // ---------------------------------------------------------------
        // Column sweep (solve tridiagonal systems column-wise, updating v)
        // ---------------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // C: v[0][i] = 1.0;
            v(i, 0) = num_t(1.0);

            // C: p[i][0] = 0.0; q[i][0] = v[0][i];
            p(0, i) = num_t(0.0);
            q(0, i) = v(i, 0);

            // Forward sweep in j: j = 1 .. n-2
            for (int j = 1; j < n - 1; j++) {
                // C indices:
                //   p[i][j]   -> p(j, i)
                //   p[i][j-1] -> p(j-1, i)
                //   u[j][i-1] -> u(i-1, j)
                //   u[j][i]   -> u(i,   j)
                //   u[j][i+1] -> u(i+1, j)
                //   q[i][j-1] -> q(j-1, i)

                num_t denom = a * p(j - 1, i) + b;
                p(j, i) = -c / denom;

                q(j, i) = (-d * u(i - 1, j) +
                           (num_t(1.0) + num_t(2.0) * d) * u(i, j) -
                           f * u(i + 1, j) -
                           a * q(j - 1, i)) / denom;
            }

            // C: v[n-1][i] = 1.0;
            v(i, n - 1) = num_t(1.0);

            // Backward substitution: j = n-2 .. 1
            for (int j = n - 2; j >= 1; j--) {
                // C: v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                // HL mapping:
                //   v[j][i]   -> v(i, j)
                //   v[j+1][i] -> v(i, j+1)
                //   p[i][j]   -> p(j, i)
                //   q[i][j]   -> q(j, i)
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // -----------------------------------------------------------
        // Row sweep (solve tridiagonal systems row-wise, updating u)
        // -----------------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            // C: u[i][0] = 1.0;
            u(0, i) = num_t(1.0);

            // C: p[i][0] = 0.0; q[i][0] = u[i][0];
            p(0, i) = num_t(0.0);
            q(0, i) = u(0, i);

            // Forward sweep in j: j = 1 .. n-2
            for (int j = 1; j < n - 1; j++) {
                // C indices:
                //   p[i][j]     -> p(j, i)
                //   p[i][j-1]   -> p(j-1, i)
                //   v[i-1][j]   -> v(j, i-1)
                //   v[i][j]     -> v(j, i)
                //   v[i+1][j]   -> v(j, i+1)
                //   q[i][j-1]   -> q(j-1, i)

                num_t denom = d * p(j - 1, i) + e;
                p(j, i) = -f / denom;

                q(j, i) = (-a * v(j, i - 1) +
                           (num_t(1.0) + num_t(2.0) * a) * v(j, i) -
                           c * v(j, i + 1) -
                           d * q(j - 1, i)) / denom;
            }

            // C: u[i][n-1] = 1.0;
            u(n - 1, i) = num_t(1.0);

            // Backward substitution: j = n-2 .. 1
            for (int j = n - 2; j >= 1; j--) {
                // C: u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                // HL mapping:
                //   u[i][j]   -> u(j,   i)
                //   u[i][j+1] -> u(j+1, i)
                //   p[i][j]   -> p(j,   i)
                //   q[i][j]   -> q(j,   i)
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size and number of time steps.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 2D Buffers for u, v, p, q.
    //
    // Mapping: C arrays u[n][n] -> Buffer<num_t,2> u(n, n),
    // with u(i_c, j_c) in C corresponding to u(j_c, i_c) here.
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u.
    init_array(n, u);

    // Measure kernel execution time.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting u to stderr (similar spirit to PolyBench's print_array).
