    DX = SCALAR_VAL(1.0) / (num_t)n;
    DY = SCALAR_VAL(1.0) / (num_t)n;
    DT = SCALAR_VAL(1.0) / (num_t)tsteps;
    B1 = SCALAR_VAL(2.0);
    B2 = SCALAR_VAL(1.0);
    mul1 = B1 * DT / (DX * DX);
    mul2 = B2 * DT / (DY * DY);

    a = -mul1 / SCALAR_VAL(2.0);
    b = SCALAR_VAL(1.0) + mul1;
    c = a;
    d = -mul2 / SCALAR_VAL(2.0);
    e = SCALAR_VAL(1.0) + mul2;
    f = d;

    for (t = 1; t <= tsteps; t++) {
        // -------------------------------------------------------------
        // Column sweep
        // -------------------------------------------------------------
        for (i = 1; i < n - 1; i++) {
            ARR(v, 0,     i) = SCALAR_VAL(1.0);
            ARR(p, i,     0) = SCALAR_VAL(0.0);
            ARR(q, i,     0) = ARR(v, 0, i);

            for (j = 1; j < n - 1; j++) {
                ARR(p, i, j) = -c / (a * ARR(p, i, j - 1) + b);

                ARR(q, i, j) =
                    ( -d * ARR(u, j, i - 1)
                      + (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * d) * ARR(u, j, i)
                      - f * ARR(u, j, i + 1)
                      - a * ARR(q, i, j - 1) )
                    / (a * ARR(p, i, j - 1) + b);
            }

            ARR(v, n - 1, i) = SCALAR_VAL(1.0);

            for (j = n - 2; j >= 1; j--) {
                ARR(v, j, i) = ARR(p, i, j) * ARR(v, j + 1, i) + ARR(q, i, j);
            }
        }

        // -------------------------------------------------------------
        // Row sweep
        // -------------------------------------------------------------
        for (i = 1; i < n - 1; i++) {
            ARR(u, i,     0) = SCALAR_VAL(1.0);
            ARR(p, i,     0) = SCALAR_VAL(0.0);
            ARR(q, i,     0) = ARR(u, i, 0);

            for (j = 1; j < n - 1; j++) {
                ARR(p, i, j) = -f / (d * ARR(p, i, j - 1) + e);

                ARR(q, i, j) =
                    ( -a * ARR(v, i - 1, j)
                      + (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * a) * ARR(v, i, j)
                      - c * ARR(v, i + 1, j)
                      - d * ARR(q, i, j - 1) )
                    / (d * ARR(p, i, j - 1) + e);
            }

            ARR(u, i, n - 1) = SCALAR_VAL(1.0);

            for (j = n - 2; j >= 1; j--) {
                ARR(u, i, j) = ARR(p, i, j) * ARR(u, i, j + 1) + ARR(q, i, j);
            }
        }
    }
}

