    int tsteps = TSTEPS;

    // Buffers for u, v, p, q.
    //
    // C arrays are declared as u[N][N], and accessed as u[i][j].
    // We store them as Halide::Buffer<num_t, 2> with shape (n, n)
    // and interpret ARR(buf, i, j) == buf(j, i).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
